<template>
  <v-card
    class="mx-auto"
    max-width="500"
  >
    <v-toolbar
      color="#1565C0"
      dark
      style="text-align: center;" 
    >

      <v-toolbar-title >Messages</v-toolbar-title>

      <v-spacer></v-spacer>

      <v-btn icon>
        <!-- <v-icon>mdi-magnify</v-icon> -->
      </v-btn>
    </v-toolbar>

    <v-list subheader>
      <v-subheader>Recent Chats</v-subheader>

      <v-list-item
        v-for="chat in recent"
        :key="chat._id"
      >
      
        <v-list-item-avatar>
          <!-- <v-img
            :src="'http://localhost:3000/profile-image/' + getAwayImg(chat.from._id, chat.to._id) + '.PNG'"
          ></v-img> -->
          <v-img
            :src="urls+ '/profile-image/' + getAwayImg(chat.from._id, chat.to._id) + '.PNG'"
             @error="handleImageError"
       
        :lazy-src="defaultAvatar"
          ></v-img>
        </v-list-item-avatar>

        <v-list-item-content>
          <v-list-item-title v-text="chat.text"></v-list-item-title>
        </v-list-item-content>


        <v-list-item-content>
            <v-list-item-title v-html="nameOfSender(chat.from, chat.to)"></v-list-item-title>
        </v-list-item-content>
        
        <v-list-item-icon>
          <v-icon :color="chat.active ? 'deep-purple accent-4' : 'grey'" @click="openNewMessage(chat.from._id, chat.to._id)">
            mdi-message-outline
          </v-icon>
        </v-list-item-icon>
      </v-list-item>
    </v-list>

    <v-divider></v-divider>

    
  </v-card>
</template>

<script>
import serverUrl from '../../config'
// import {mapActions} from 'vuex'
// import * as types from "../../store/types";
import axios from 'axios';
import io from "socket.io-client";

export default {
  
  data:() => ({
    // recent: [
    //     {
    //       active: true,
    //       avatar: 'https://cdn.vuetifyjs.com/images/lists/1.jpg',
    //       title: 'Jason Oner',
    //     },
    //     {
    //       active: true,
    //       avatar: 'https://cdn.vuetifyjs.com/images/lists/2.jpg',
    //       title: 'Mike Carlson',
    //     },
    //     {
    //       avatar: 'https://cdn.vuetifyjs.com/images/lists/3.jpg',
    //       title: 'Cindy Baker',
    //     },
    //     {
    //       avatar: 'https://cdn.vuetifyjs.com/images/lists/4.jpg',
    //       title: 'Ali Connors',
    //     },
    //   ],
   
   
    // socket: io("http://localhost:3000", {
    socket: io(serverUrl, {
             query: { token: localStorage.getItem("token") },
             }),
    recent: [],
    name: '', 
    from: '',
    to: '',
    urls: serverUrl,
     profileImage: '', // سيتم تعبئتها في created
      fallbackImage: '',
      defaultAvatar: require('@/assets/avatar.png')
  }),
  created() {
      this.fallbackImage = this.urls + '/profile-image/avatar.png';

    // this.getAllMessage()
    this.socket.emit('some', 'some')
    //  axios.get("http://localhost:3000/get-all-messages",
     axios.get(this.urls + "/get-all-messages",
       {
        headers: {
          authorization: localStorage.getItem("token"),
        },
      }).then((res) => {
        var ret = new Array;
        for(var i = res.data.length-1; i >= 0; i--) {
          ret.push(res.data[i]);
         }
         
        this.recent = ret
          this.sortArrayByDate(this.recent)  

        
      });


       this.socket.on("new-msg-list", (msg) => {
        for (let i = 0; i < this.recent.length; i++) {
          if ( (this.recent[i].from._id == msg.from._id && this.recent[i].from == msg.from._id) ||
             (this.recent[i].to._id == msg.to._id && this.recent[i].to._id == msg.to._id) ||
             (this.recent[i].from_id == msg.to._id && this.recent[i].to._id == msg.from._id) ||
            (this.recent[i].to._id == msg.from._id && this.recent[i].from._id== msg.to._id) ) {
              this.recent.splice(i, 1)
             
              }
        }
         this.recent.push(msg)
          this.nameOfSender(msg.from._id, msg.to._id) 
        this.sortArrayByDate(this.recent)
      })

      this.socket.on("new-msg-list2", (msg) => {
        for (let i = 0; i < this.recent.length; i++) {
          if ( (this.recent[i].from._id == msg.from._id && this.recent[i].from == msg.from._id) ||
             (this.recent[i].to._id == msg.to._id && this.recent[i].to._id == msg.to._id) ||
             (this.recent[i].from_id == msg.to._id && this.recent[i].to._id == msg.from._id) ||
            (this.recent[i].to._id == msg.from._id && this.recent[i].from._id== msg.to._id) ) {
              this.recent.splice(i, 1)
             
              }
        }
         this.recent.push(msg)
          this.nameOfSender(msg.from._id, msg.to._id) 
        this.sortArrayByDate(this.recent)
      })
  },

  methods: {
    handleImageError(event) {
   if (event.target) {
      event.target.src = this.defaultAvatar;
    } else {
      // إذا كان event هو كائن Vuetify:
      return this.defaultAvatar;
    }
  },
  //   ...mapActions({
  //   getAllMessage: types.GET_ALL_MESSAGES
  // }),
    
    // sendMessage() {
    //   this.$store.dispatch('socketOnConnection', {msg: 'sosa', id: '5fdf3939a083b610dcf547f9'})
    // }

    getAwayImg(first, second) {
      return first == localStorage.getItem('userID') ? second : first
    },
    
      nameOfSender(from, to) {
      if (from._id == localStorage.getItem('userID')) {
        return `
      <div style="
        display: inline-flex;
        align-items: center;
        gap: 6px;
        font-family: 'Roboto', sans-serif;
      ">
        <span style="
          font-weight: 600;
          color: #1976d2;
          background: #e3f2fd;
          padding: 2px 8px;
          border-radius: 12px;
        ">You</span>
        <span style="
          color: #1976d2;
          font-weight: bold;
        ">→</span>
        <span style="
          color: #333;
        ">${to.name}</span>
      </div>
    `;
       
        
      } else {
       return `
      <div style="
        display: inline-flex;
        align-items: center;
        gap: 6px;
        font-family: 'Roboto', sans-serif;
      ">
        <span style="
          color: #333;
        ">You</span>
        <span style="
          color: #9c27b0;
          font-weight: bold;
        ">←</span>
        <span style="
          font-weight: 600;
          color: #9c27b0;
          background: #f3e5f5;
          padding: 2px 8px;
          border-radius: 12px;
        ">${from.name}</span>
      </div>
    `;  
      }
    }, 

    sortArrayByDate(arr) {
      arr.sort(function(a, b) {
            var c = new Date(a.date);
            var d = new Date(b.date);
            return d -c ;
        });   
    },
    openNewMessage(firstId, secondId) {
      if(localStorage.getItem('userID') == secondId) {
        this.$router.push({name:'private-chat', params: {receiverID: firstId}})
      } else {
        this.$router.push({name:'private-chat', params: {receiverID: secondId}})
      }
      
    },
   
    testImage(url) {
      return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => resolve(true);
        img.onerror = () => resolve(false);
        img.src = url;
      });
    },
  }


}
</script>

